<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount } from 'vue'
import SubingReplayChart from './SubingReplayChart.vue'
import { label as decisionLabel } from './labels'
const data=ref<any>(null),error=ref(''),loading=ref(false)
const appliedCost=computed(()=>data.value?.cost_policy)
const registeredCost=computed(()=>data.value?.registered_cost_policy)
const cost=computed(()=>appliedCost.value??registeredCost.value)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const labels:Record<string,string>={EXECUTION_FACTS_INTERRUPTED_REVIEW_REQUIRED:'执行事实中断，保留义务，待人工复核',DAILY_FACTS_INTERRUPTED_REVIEW_REQUIRED:'日线事实中断，保留义务，待人工复核',OBSERVING:'持续观察',OBSERVATION_READY:'预热就绪，等待新Bar',WARMUP_INCOMPLETE:'预热不足',EXECUTION_FACTS_MISSING:'当前执行事实不足',DAILY_FACTS_MISSING:'最新日线事实不足',ROLLOVER_WAIT:'换月待处理，暂停新增',RUNNING:'运行中',STALE_OR_STOPPED:'进程已停止或状态过期',NOT_STARTED:'尚未启动',WAIT_EXECUTION_FACTS_OR_FIRST_OBSERVATION:'等待执行事实或首个新完成Bar',WAIT_FIRST_OBSERVATION:'等待首个新完成Bar',TREND_UP:'上涨趋势',TREND_DOWN:'下跌趋势',RANGE:'震荡',UNKNOWN:'未知',UP:'向上',DOWN:'向下',NEUTRAL:'中性',LONG:'多头',SHORT:'空头',HOLD:'持有',HOLD_NO_ADD:'持有，暂停加仓',WAIT:'等待',RECORD_ONLY:'日终记录',WAIT_CONFIRMATION:'等待破位确认',EXIT_OBLIGATION:'处理退出义务',REDUCE_OBLIGATION:'处理减仓义务',CHECK_ENTRY_ELIGIBILITY:'首仓资格通过',CHECK_ADD_ELIGIBILITY:'加仓资格通过'}
const label=(v:string)=>labels[v]??decisionLabel(v)
const money=(v:any)=>v==null?'未知':Number(v).toFixed(2)
const stamp=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无'
async function load(){if(disposed)return;loading.value=true;try{const r=await fetch('/api/v1/subing-model/status');if(!r.ok)throw Error();const next=await r.json();if(!disposed){data.value=next;error.value=''}}catch{if(!disposed)error.value='持续模型读取失败，保留上一快照；该快照不代表当前状态。'}finally{if(!disposed){loading.value=false;timer=setTimeout(load,10000)}}}
function refresh(){clearTimeout(timer);void load()}
onMounted(load);onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
</script>
<template><div class="continuous-model"><div class="model-toolbar"><strong>开发环境持续模型</strong><span>{{label(data?.worker_status??data?.status)}}</span><button :disabled="loading" @click="refresh">刷新</button></div><p v-if="error" role="alert">{{error}}</p><template v-if="data?.account"><p class="model-note">启动：{{stamp(data.started_at)}} · 空仓启动，历史仅预热 · 后续完成1m收盘＋1tick滑点 · {{data.run_id}} · 焦煤独立10万元账户</p><p v-if="cost" class="model-note">费用口径：{{cost.assumption.assumed?'模型费率假设：沿用同合约前一交易日完整费率':'当日完整费率'}} · 来源 {{cost.assumption.source_day}} → 用于 {{cost.assumption.target_day}} · {{cost.assumption.contract}}<br>版本 {{cost.version}} · {{appliedCost?'已写入后续观察日志':'已登记，等待新的完成Bar消费'}}。{{cost.assumption.assumed?'手续费可能与当日实际值不同；保证金、昨结算与涨跌停仍使用当日事实。':''}}<br>手续费类型 {{cost.assumption.source_parameters[0].commission_type==='by_money'?'按成交额比例':'按手收费'}} · 开仓 {{cost.assumption.source_parameters[0].open_commission}} · 平仓 {{cost.assumption.source_parameters[0].close_commission}} · 平今 {{cost.assumption.source_parameters[0].close_commission_today}}</p><div class="model-grid"><section><h2>焦煤模型账户</h2><p>{{label(data.account.status)}}</p><div class="money-grid"><div>权益<strong>{{money(data.account.equity??data.account.cash)}} 元</strong></div><div>仓位<strong>{{data.account.summary?.open_quantity??data.account.open_quantity??0}} 手</strong></div><div>净损益<strong>{{money(data.account.net_pnl)}} 元</strong></div></div><p v-if="data.account.protection_observation" class="model-note">当前保护需求：{{label(data.account.protection_observation.demand)}} · 已知退出依据 {{data.account.protection_observation.required_full_exit.join('、')||'无新增全清'}}；等待权威事实和人工复核，权益仍为最后可信估值。</p><p v-else-if="data.account.latest_decision">当前需求：{{label(data.account.latest_decision.demand)}} · {{label(data.account.latest_decision.reason)}}</p><p v-if="data.account.latest_decision">等待：{{label(data.account.latest_decision.next_wait)}} · 条件缺口：{{data.account.latest_decision.condition_gaps.map(label).join('、')||'无'}}<br>支持：{{data.account.latest_decision.supporting_reasons.map(label).join('、')||'无'}} · 阻止：{{data.account.latest_decision.blocking_reasons.map(label).join('、')||'无'}}</p><p>事实时刻：{{stamp(data.account.valuation_at)}} · 实际获知：{{stamp(data.account.observed_at)}}</p><p>未成交退出义务和旧合约持仓保持；缺口、换月及执行事实不足均不假装成交。</p></section><section><h2>焦煤最新观察</h2><SubingReplayChart :rows="data.chart??[]" :stop="data.account.decision_state?.initial_stop??null" :target="data.account.decision_state?.profit_target??null"/></section></div><section><h2>14品种观察与适配</h2><p class="model-note">仅焦煤接入模型撮合。其余品种参数为固定ATR尺度研究候选，未经确认不启用账户；不汇总组合收益。</p><table><thead><tr><th>品种 / 合约</th><th>状态</th><th>日线 / 30m / 60m</th><th>最新完成Bar</th><th>候选近轴 / 极端 / 止损缓冲</th></tr></thead><tbody><tr v-for="p in data.products" :key="p.product"><td>{{p.product.toUpperCase()}} · {{p.contract}}</td><td>{{label(p.status)}}<small v-if="p.warmup_only">启动预热快照</small></td><td>{{label(p.daily?.direction)}} / {{label(p.regime)}} / {{label(p.hourly?.direction)}}</td><td>{{stamp(p.bar_end)}}</td><td>{{money(p.normalization_candidate?.near_axis)}} / {{money(p.normalization_candidate?.extreme_macd)}} / {{money(p.normalization_candidate?.stop_buffer)}}<small>研究值，未做tick执行取整</small></td></tr></tbody></table></section><section><h2>模型持仓与未决动作</h2><p>毛浮盈 {{money(data.account.unrealized)}} 元 · 已扣费用 {{money(data.account.fees)}} 元 · 保护价 {{money(data.account.decision_state?.initial_stop)}} · 1R目标 {{money(data.account.decision_state?.profit_target)}}</p><p>未决动作：{{data.account.pending?label(data.account.pending.kind):'无'}} · {{data.account.pending?.reasons.map(label).join('、')||'无未决触发原因'}}</p><table v-if="data.account.open_layers?.length"><thead><tr><th>持仓层</th><th>方向</th><th>成本</th><th>模型入场时刻</th></tr></thead><tbody><tr v-for="l in data.account.open_layers" :key="l.layer_id"><td>{{label(l.kind)}} · {{l.layer_id}}</td><td>{{label(l.side)}}</td><td>{{money(l.price)}}</td><td>{{stamp(l.at)}}</td></tr></tbody></table><p v-else>当前无模型持仓。</p></section><section><h2>最近决策历史</h2><table v-if="data.account.decision_history?.length"><thead><tr><th>事实时刻</th><th>阶段</th><th>主需求</th><th>依据</th><th>等待</th></tr></thead><tbody><tr v-for="r in [...data.account.decision_history].reverse()" :key="r.at"><td>{{stamp(r.at)}}</td><td>{{label(r.phase)}}</td><td>{{label(r.demand)}}</td><td>{{label(r.reason)}}</td><td>{{label(r.next_wait)}}</td></tr></tbody></table><p v-else>暂无启动后的模型决策；历史预热不产生账户动作。</p></section><section><h2>模型成交</h2><p v-if="!data.account.fills?.length">尚无模型成交；启用和健康状态不代表发生了成交。</p><table v-else><thead><tr><th>实际观察时间</th><th>合约</th><th>动作</th><th>价格</th><th>费用</th></tr></thead><tbody><tr v-for="f in data.account.fills" :key="f.fill_id"><td>{{stamp(f.fill_at)}}</td><td>{{f.contract}}</td><td>{{label(f.action)}}</td><td>{{money(f.price)}}</td><td>{{money(f.fee)}}</td></tr></tbody></table></section></template><p v-else-if="data?.status==='NOT_STARTED' && !loading && !error">持续模型尚未初始化。</p></div></template>
<style scoped>.model-toolbar{display:flex;gap:20px;align-items:center;padding:14px 0}.model-toolbar button{margin-left:auto;background:white;border:1px solid #ebedf0;border-radius:6px;padding:7px 16px;color:#ff6b2c}.model-toolbar span,.model-note{font-size:12px;color:#667085}.model-grid{display:grid;grid-template-columns:1fr 1.4fr;gap:16px}section{border:1px solid #ebedf0;border-radius:8px;background:#fff;padding:18px;margin:12px 0}h2{font-size:16px;margin:0 0 16px}.money-grid{display:flex;justify-content:space-between;margin:30px 0;font-size:12px;color:#667085}.money-grid strong{display:block;font-size:20px;color:#20242b;margin-top:10px}p{font-size:13px;line-height:1.7}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px 10px;border-bottom:1px solid #ebedf0;text-align:left}th{color:#667085;font-weight:500;background:#f8f9fb}small{display:block;color:#667085;font-size:11px;margin-top:4px}[role=alert]{color:#b66526;background:#fff4ee;padding:12px}</style>
